template< std::size_t TDim, std::size_t TNumNodes, bool TNormalVariation, std::size_t TNumNodesMaster>
void AugmentedLagrangianMethodFrictionlessMortarContactCondition<TDim,TNumNodes,TNormalVariation, TNumNodesMaster>::CalculateLocalRHS(
    Vector& rLocalRHS,
    const MortarConditionMatrices& rMortarConditionMatrices,
    const DerivativeDataType& rDerivativeData,
    const IndexType rActiveInactive,
    const ProcessInfo& rCurrentProcessInfo
    )
{
    StaticCalculateLocalRHS(this, rLocalRHS, rMortarConditionMatrices, rDerivativeData, rActiveInactive, rCurrentProcessInfo);
}

/***************************** BEGIN AD REPLACEMENT ********************************/
/***********************************************************************************/

template<>
void AugmentedLagrangianMethodFrictionlessMortarContactCondition<2,2, false, 2>::StaticCalculateLocalRHS(
    PairedCondition* pCondition,
    Vector& rLocalRHS,
    const MortarConditionMatrices& rMortarConditionMatrices,
    const DerivativeDataType& rDerivativeData,
    const IndexType rActiveInactive,
    const ProcessInfo& rCurrentProcessInfo
    )
{
    // Initialize
    for (std::size_t i = 0; i < 10; ++i)
        rLocalRHS[i] = 0.0;

    // The geometry of the condition
    const GeometryType& r_geometry = pCondition->GetParentGeometry();

    // Initialize values
    const BoundedMatrix<double, 2, 2>& u1 = rDerivativeData.u1;
    const BoundedMatrix<double, 2, 2>& u2 = rDerivativeData.u2;
    const BoundedMatrix<double, 2, 2>& X1 = rDerivativeData.X1;
    const BoundedMatrix<double, 2, 2>& X2 = rDerivativeData.X2;

    const array_1d<double, 2> LMNormal = MortarUtilities::GetVariableVector<2>(r_geometry, LAGRANGE_MULTIPLIER_CONTACT_PRESSURE, 0);

    const BoundedMatrix<double, 2, 2>& NormalSlave = rDerivativeData.NormalSlave;

    // The ALM parameters
    const array_1d<double, 2> DynamicFactor = MortarUtilities::GetVariableVector<2>(r_geometry, DYNAMIC_FACTOR);
    const double ScaleFactor = rDerivativeData.ScaleFactor;
    const array_1d<double, 2>& PenaltyParameter = rDerivativeData.PenaltyParameter;

    // Mortar operators
    const BoundedMatrix<double, 2, 2>& MOperator = rMortarConditionMatrices.MOperator;
    const BoundedMatrix<double, 2, 2>& DOperator = rMortarConditionMatrices.DOperator;


    // NODE 0
    if (r_geometry[0].IsNot(ACTIVE)) { // INACTIVE

        rLocalRHS[8]+=-LMNormal[0]*std::pow(ScaleFactor, 2)/PenaltyParameter[0];
    } else { // ACTIVE
        const double crhs0 =     NormalSlave(0,0)*(DOperator(0,0)*(X1(0,0) + u1(0,0)) + DOperator(0,1)*(X1(1,0) + u1(1,0)) - MOperator(0,0)*(X2(0,0) + u2(0,0)) - MOperator(0,1)*(X2(1,0) + u2(1,0))) + NormalSlave(0,1)*(DOperator(0,0)*(X1(0,1) + u1(0,1)) + DOperator(0,1)*(X1(1,1) + u1(1,1)) - MOperator(0,0)*(X2(0,1) + u2(0,1)) - MOperator(0,1)*(X2(1,1) + u2(1,1)));
        const double crhs1 =     DynamicFactor[0]*(LMNormal[0]*ScaleFactor - PenaltyParameter[0]*crhs0);
        const double crhs2 =     MOperator(0,0)*crhs1;
        const double crhs3 =     MOperator(0,1)*crhs1;
        const double crhs4 =     DOperator(0,0)*crhs1;
        const double crhs5 =     DOperator(0,1)*crhs1;

        rLocalRHS[0]+=-NormalSlave(0,0)*crhs2;
        rLocalRHS[1]+=-NormalSlave(0,1)*crhs2;
        rLocalRHS[2]+=-NormalSlave(0,0)*crhs3;
        rLocalRHS[3]+=-NormalSlave(0,1)*crhs3;
        rLocalRHS[4]+=NormalSlave(0,0)*crhs4;
        rLocalRHS[5]+=NormalSlave(0,1)*crhs4;
        rLocalRHS[6]+=NormalSlave(0,0)*crhs5;
        rLocalRHS[7]+=NormalSlave(0,1)*crhs5;
        rLocalRHS[8]+=-ScaleFactor*crhs0;
    }

    // NODE 1
    if (r_geometry[1].IsNot(ACTIVE)) { // INACTIVE

        rLocalRHS[9]+=-LMNormal[1]*std::pow(ScaleFactor, 2)/PenaltyParameter[1];
    } else { // ACTIVE
        const double crhs0 =     NormalSlave(1,0)*(DOperator(1,0)*(X1(0,0) + u1(0,0)) + DOperator(1,1)*(X1(1,0) + u1(1,0)) - MOperator(1,0)*(X2(0,0) + u2(0,0)) - MOperator(1,1)*(X2(1,0) + u2(1,0))) + NormalSlave(1,1)*(DOperator(1,0)*(X1(0,1) + u1(0,1)) + DOperator(1,1)*(X1(1,1) + u1(1,1)) - MOperator(1,0)*(X2(0,1) + u2(0,1)) - MOperator(1,1)*(X2(1,1) + u2(1,1)));
        const double crhs1 =     DynamicFactor[1]*(LMNormal[1]*ScaleFactor - PenaltyParameter[1]*crhs0);
        const double crhs2 =     MOperator(1,0)*crhs1;
        const double crhs3 =     MOperator(1,1)*crhs1;
        const double crhs4 =     DOperator(1,0)*crhs1;
        const double crhs5 =     DOperator(1,1)*crhs1;

        rLocalRHS[0]+=-NormalSlave(1,0)*crhs2;
        rLocalRHS[1]+=-NormalSlave(1,1)*crhs2;
        rLocalRHS[2]+=-NormalSlave(1,0)*crhs3;
        rLocalRHS[3]+=-NormalSlave(1,1)*crhs3;
        rLocalRHS[4]+=NormalSlave(1,0)*crhs4;
        rLocalRHS[5]+=NormalSlave(1,1)*crhs4;
        rLocalRHS[6]+=NormalSlave(1,0)*crhs5;
        rLocalRHS[7]+=NormalSlave(1,1)*crhs5;
        rLocalRHS[9]+=-ScaleFactor*crhs0;
    }
}

