template<>
void AugmentedLagrangianMethodFrictionlessMortarContactCondition<3,4, false, 3>::StaticCalculateLocalRHS(
    PairedCondition* pCondition,
    Vector& rLocalRHS,
    const MortarConditionMatrices& rMortarConditionMatrices,
    const DerivativeDataType& rDerivativeData,
    const IndexType rActiveInactive,
    const ProcessInfo& rCurrentProcessInfo
    )
{
    // Initialize
    for (std::size_t i = 0; i < 25; ++i)
        rLocalRHS[i] = 0.0;

    // The geometry of the condition
    const GeometryType& r_geometry = pCondition->GetParentGeometry();

    // Initialize values
    const BoundedMatrix<double, 4, 3>& u1 = rDerivativeData.u1;
    const BoundedMatrix<double, 3, 3>& u2 = rDerivativeData.u2;
    const BoundedMatrix<double, 4, 3>& X1 = rDerivativeData.X1;
    const BoundedMatrix<double, 3, 3>& X2 = rDerivativeData.X2;

    const array_1d<double, 4> LMNormal = MortarUtilities::GetVariableVector<4>(r_geometry, LAGRANGE_MULTIPLIER_CONTACT_PRESSURE, 0);

    const BoundedMatrix<double, 4, 3>& NormalSlave = rDerivativeData.NormalSlave;

    // The ALM parameters
    const array_1d<double, 4> DynamicFactor = MortarUtilities::GetVariableVector<4>(r_geometry, DYNAMIC_FACTOR);
    const double ScaleFactor = rDerivativeData.ScaleFactor;
    const array_1d<double, 4>& PenaltyParameter = rDerivativeData.PenaltyParameter;

    // Mortar operators
    const BoundedMatrix<double, 4, 3>& MOperator = rMortarConditionMatrices.MOperator;
    const BoundedMatrix<double, 4, 4>& DOperator = rMortarConditionMatrices.DOperator;


    // NODE 0
    if (r_geometry[0].IsNot(ACTIVE)) { // INACTIVE

        rLocalRHS[21]+=-LMNormal[0]*std::pow(ScaleFactor, 2)/PenaltyParameter[0];
    } else { // ACTIVE
        const double crhs0 =     NormalSlave(0,0)*(DOperator(0,0)*(X1(0,0) + u1(0,0)) + DOperator(0,1)*(X1(1,0) + u1(1,0)) + DOperator(0,2)*(X1(2,0) + u1(2,0)) + DOperator(0,3)*(X1(3,0) + u1(3,0)) - MOperator(0,0)*(X2(0,0) + u2(0,0)) - MOperator(0,1)*(X2(1,0) + u2(1,0)) - MOperator(0,2)*(X2(2,0) + u2(2,0))) + NormalSlave(0,1)*(DOperator(0,0)*(X1(0,1) + u1(0,1)) + DOperator(0,1)*(X1(1,1) + u1(1,1)) + DOperator(0,2)*(X1(2,1) + u1(2,1)) + DOperator(0,3)*(X1(3,1) + u1(3,1)) - MOperator(0,0)*(X2(0,1) + u2(0,1)) - MOperator(0,1)*(X2(1,1) + u2(1,1)) - MOperator(0,2)*(X2(2,1) + u2(2,1))) + NormalSlave(0,2)*(DOperator(0,0)*(X1(0,2) + u1(0,2)) + DOperator(0,1)*(X1(1,2) + u1(1,2)) + DOperator(0,2)*(X1(2,2) + u1(2,2)) + DOperator(0,3)*(X1(3,2) + u1(3,2)) - MOperator(0,0)*(X2(0,2) + u2(0,2)) - MOperator(0,1)*(X2(1,2) + u2(1,2)) - MOperator(0,2)*(X2(2,2) + u2(2,2)));
        const double crhs1 =     DynamicFactor[0]*(LMNormal[0]*ScaleFactor - PenaltyParameter[0]*crhs0);
        const double crhs2 =     MOperator(0,0)*crhs1;
        const double crhs3 =     MOperator(0,1)*crhs1;
        const double crhs4 =     MOperator(0,2)*crhs1;
        const double crhs5 =     DOperator(0,0)*crhs1;
        const double crhs6 =     DOperator(0,1)*crhs1;
        const double crhs7 =     DOperator(0,2)*crhs1;
        const double crhs8 =     DOperator(0,3)*crhs1;

        rLocalRHS[0]+=-NormalSlave(0,0)*crhs2;
        rLocalRHS[1]+=-NormalSlave(0,1)*crhs2;
        rLocalRHS[2]+=-NormalSlave(0,2)*crhs2;
        rLocalRHS[3]+=-NormalSlave(0,0)*crhs3;
        rLocalRHS[4]+=-NormalSlave(0,1)*crhs3;
        rLocalRHS[5]+=-NormalSlave(0,2)*crhs3;
        rLocalRHS[6]+=-NormalSlave(0,0)*crhs4;
        rLocalRHS[7]+=-NormalSlave(0,1)*crhs4;
        rLocalRHS[8]+=-NormalSlave(0,2)*crhs4;
        rLocalRHS[9]+=NormalSlave(0,0)*crhs5;
        rLocalRHS[10]+=NormalSlave(0,1)*crhs5;
        rLocalRHS[11]+=NormalSlave(0,2)*crhs5;
        rLocalRHS[12]+=NormalSlave(0,0)*crhs6;
        rLocalRHS[13]+=NormalSlave(0,1)*crhs6;
        rLocalRHS[14]+=NormalSlave(0,2)*crhs6;
        rLocalRHS[15]+=NormalSlave(0,0)*crhs7;
        rLocalRHS[16]+=NormalSlave(0,1)*crhs7;
        rLocalRHS[17]+=NormalSlave(0,2)*crhs7;
        rLocalRHS[18]+=NormalSlave(0,0)*crhs8;
        rLocalRHS[19]+=NormalSlave(0,1)*crhs8;
        rLocalRHS[20]+=NormalSlave(0,2)*crhs8;
        rLocalRHS[21]+=-ScaleFactor*crhs0;
    }

    // NODE 1
    if (r_geometry[1].IsNot(ACTIVE)) { // INACTIVE

        rLocalRHS[22]+=-LMNormal[1]*std::pow(ScaleFactor, 2)/PenaltyParameter[1];
    } else { // ACTIVE
        const double crhs0 =     NormalSlave(1,0)*(DOperator(1,0)*(X1(0,0) + u1(0,0)) + DOperator(1,1)*(X1(1,0) + u1(1,0)) + DOperator(1,2)*(X1(2,0) + u1(2,0)) + DOperator(1,3)*(X1(3,0) + u1(3,0)) - MOperator(1,0)*(X2(0,0) + u2(0,0)) - MOperator(1,1)*(X2(1,0) + u2(1,0)) - MOperator(1,2)*(X2(2,0) + u2(2,0))) + NormalSlave(1,1)*(DOperator(1,0)*(X1(0,1) + u1(0,1)) + DOperator(1,1)*(X1(1,1) + u1(1,1)) + DOperator(1,2)*(X1(2,1) + u1(2,1)) + DOperator(1,3)*(X1(3,1) + u1(3,1)) - MOperator(1,0)*(X2(0,1) + u2(0,1)) - MOperator(1,1)*(X2(1,1) + u2(1,1)) - MOperator(1,2)*(X2(2,1) + u2(2,1))) + NormalSlave(1,2)*(DOperator(1,0)*(X1(0,2) + u1(0,2)) + DOperator(1,1)*(X1(1,2) + u1(1,2)) + DOperator(1,2)*(X1(2,2) + u1(2,2)) + DOperator(1,3)*(X1(3,2) + u1(3,2)) - MOperator(1,0)*(X2(0,2) + u2(0,2)) - MOperator(1,1)*(X2(1,2) + u2(1,2)) - MOperator(1,2)*(X2(2,2) + u2(2,2)));
        const double crhs1 =     DynamicFactor[1]*(LMNormal[1]*ScaleFactor - PenaltyParameter[1]*crhs0);
        const double crhs2 =     MOperator(1,0)*crhs1;
        const double crhs3 =     MOperator(1,1)*crhs1;
        const double crhs4 =     MOperator(1,2)*crhs1;
        const double crhs5 =     DOperator(1,0)*crhs1;
        const double crhs6 =     DOperator(1,1)*crhs1;
        const double crhs7 =     DOperator(1,2)*crhs1;
        const double crhs8 =     DOperator(1,3)*crhs1;

        rLocalRHS[0]+=-NormalSlave(1,0)*crhs2;
        rLocalRHS[1]+=-NormalSlave(1,1)*crhs2;
        rLocalRHS[2]+=-NormalSlave(1,2)*crhs2;
        rLocalRHS[3]+=-NormalSlave(1,0)*crhs3;
        rLocalRHS[4]+=-NormalSlave(1,1)*crhs3;
        rLocalRHS[5]+=-NormalSlave(1,2)*crhs3;
        rLocalRHS[6]+=-NormalSlave(1,0)*crhs4;
        rLocalRHS[7]+=-NormalSlave(1,1)*crhs4;
        rLocalRHS[8]+=-NormalSlave(1,2)*crhs4;
        rLocalRHS[9]+=NormalSlave(1,0)*crhs5;
        rLocalRHS[10]+=NormalSlave(1,1)*crhs5;
        rLocalRHS[11]+=NormalSlave(1,2)*crhs5;
        rLocalRHS[12]+=NormalSlave(1,0)*crhs6;
        rLocalRHS[13]+=NormalSlave(1,1)*crhs6;
        rLocalRHS[14]+=NormalSlave(1,2)*crhs6;
        rLocalRHS[15]+=NormalSlave(1,0)*crhs7;
        rLocalRHS[16]+=NormalSlave(1,1)*crhs7;
        rLocalRHS[17]+=NormalSlave(1,2)*crhs7;
        rLocalRHS[18]+=NormalSlave(1,0)*crhs8;
        rLocalRHS[19]+=NormalSlave(1,1)*crhs8;
        rLocalRHS[20]+=NormalSlave(1,2)*crhs8;
        rLocalRHS[22]+=-ScaleFactor*crhs0;
    }

    // NODE 2
    if (r_geometry[2].IsNot(ACTIVE)) { // INACTIVE

        rLocalRHS[23]+=-LMNormal[2]*std::pow(ScaleFactor, 2)/PenaltyParameter[2];
    } else { // ACTIVE
        const double crhs0 =     NormalSlave(2,0)*(DOperator(2,0)*(X1(0,0) + u1(0,0)) + DOperator(2,1)*(X1(1,0) + u1(1,0)) + DOperator(2,2)*(X1(2,0) + u1(2,0)) + DOperator(2,3)*(X1(3,0) + u1(3,0)) - MOperator(2,0)*(X2(0,0) + u2(0,0)) - MOperator(2,1)*(X2(1,0) + u2(1,0)) - MOperator(2,2)*(X2(2,0) + u2(2,0))) + NormalSlave(2,1)*(DOperator(2,0)*(X1(0,1) + u1(0,1)) + DOperator(2,1)*(X1(1,1) + u1(1,1)) + DOperator(2,2)*(X1(2,1) + u1(2,1)) + DOperator(2,3)*(X1(3,1) + u1(3,1)) - MOperator(2,0)*(X2(0,1) + u2(0,1)) - MOperator(2,1)*(X2(1,1) + u2(1,1)) - MOperator(2,2)*(X2(2,1) + u2(2,1))) + NormalSlave(2,2)*(DOperator(2,0)*(X1(0,2) + u1(0,2)) + DOperator(2,1)*(X1(1,2) + u1(1,2)) + DOperator(2,2)*(X1(2,2) + u1(2,2)) + DOperator(2,3)*(X1(3,2) + u1(3,2)) - MOperator(2,0)*(X2(0,2) + u2(0,2)) - MOperator(2,1)*(X2(1,2) + u2(1,2)) - MOperator(2,2)*(X2(2,2) + u2(2,2)));
        const double crhs1 =     DynamicFactor[2]*(LMNormal[2]*ScaleFactor - PenaltyParameter[2]*crhs0);
        const double crhs2 =     MOperator(2,0)*crhs1;
        const double crhs3 =     MOperator(2,1)*crhs1;
        const double crhs4 =     MOperator(2,2)*crhs1;
        const double crhs5 =     DOperator(2,0)*crhs1;
        const double crhs6 =     DOperator(2,1)*crhs1;
        const double crhs7 =     DOperator(2,2)*crhs1;
        const double crhs8 =     DOperator(2,3)*crhs1;

        rLocalRHS[0]+=-NormalSlave(2,0)*crhs2;
        rLocalRHS[1]+=-NormalSlave(2,1)*crhs2;
        rLocalRHS[2]+=-NormalSlave(2,2)*crhs2;
        rLocalRHS[3]+=-NormalSlave(2,0)*crhs3;
        rLocalRHS[4]+=-NormalSlave(2,1)*crhs3;
        rLocalRHS[5]+=-NormalSlave(2,2)*crhs3;
        rLocalRHS[6]+=-NormalSlave(2,0)*crhs4;
        rLocalRHS[7]+=-NormalSlave(2,1)*crhs4;
        rLocalRHS[8]+=-NormalSlave(2,2)*crhs4;
        rLocalRHS[9]+=NormalSlave(2,0)*crhs5;
        rLocalRHS[10]+=NormalSlave(2,1)*crhs5;
        rLocalRHS[11]+=NormalSlave(2,2)*crhs5;
        rLocalRHS[12]+=NormalSlave(2,0)*crhs6;
        rLocalRHS[13]+=NormalSlave(2,1)*crhs6;
        rLocalRHS[14]+=NormalSlave(2,2)*crhs6;
        rLocalRHS[15]+=NormalSlave(2,0)*crhs7;
        rLocalRHS[16]+=NormalSlave(2,1)*crhs7;
        rLocalRHS[17]+=NormalSlave(2,2)*crhs7;
        rLocalRHS[18]+=NormalSlave(2,0)*crhs8;
        rLocalRHS[19]+=NormalSlave(2,1)*crhs8;
        rLocalRHS[20]+=NormalSlave(2,2)*crhs8;
        rLocalRHS[23]+=-ScaleFactor*crhs0;
    }

    // NODE 3
    if (r_geometry[3].IsNot(ACTIVE)) { // INACTIVE

        rLocalRHS[24]+=-LMNormal[3]*std::pow(ScaleFactor, 2)/PenaltyParameter[3];
    } else { // ACTIVE
        const double crhs0 =     NormalSlave(3,0)*(DOperator(3,0)*(X1(0,0) + u1(0,0)) + DOperator(3,1)*(X1(1,0) + u1(1,0)) + DOperator(3,2)*(X1(2,0) + u1(2,0)) + DOperator(3,3)*(X1(3,0) + u1(3,0)) - MOperator(3,0)*(X2(0,0) + u2(0,0)) - MOperator(3,1)*(X2(1,0) + u2(1,0)) - MOperator(3,2)*(X2(2,0) + u2(2,0))) + NormalSlave(3,1)*(DOperator(3,0)*(X1(0,1) + u1(0,1)) + DOperator(3,1)*(X1(1,1) + u1(1,1)) + DOperator(3,2)*(X1(2,1) + u1(2,1)) + DOperator(3,3)*(X1(3,1) + u1(3,1)) - MOperator(3,0)*(X2(0,1) + u2(0,1)) - MOperator(3,1)*(X2(1,1) + u2(1,1)) - MOperator(3,2)*(X2(2,1) + u2(2,1))) + NormalSlave(3,2)*(DOperator(3,0)*(X1(0,2) + u1(0,2)) + DOperator(3,1)*(X1(1,2) + u1(1,2)) + DOperator(3,2)*(X1(2,2) + u1(2,2)) + DOperator(3,3)*(X1(3,2) + u1(3,2)) - MOperator(3,0)*(X2(0,2) + u2(0,2)) - MOperator(3,1)*(X2(1,2) + u2(1,2)) - MOperator(3,2)*(X2(2,2) + u2(2,2)));
        const double crhs1 =     DynamicFactor[3]*(LMNormal[3]*ScaleFactor - PenaltyParameter[3]*crhs0);
        const double crhs2 =     MOperator(3,0)*crhs1;
        const double crhs3 =     MOperator(3,1)*crhs1;
        const double crhs4 =     MOperator(3,2)*crhs1;
        const double crhs5 =     DOperator(3,0)*crhs1;
        const double crhs6 =     DOperator(3,1)*crhs1;
        const double crhs7 =     DOperator(3,2)*crhs1;
        const double crhs8 =     DOperator(3,3)*crhs1;

        rLocalRHS[0]+=-NormalSlave(3,0)*crhs2;
        rLocalRHS[1]+=-NormalSlave(3,1)*crhs2;
        rLocalRHS[2]+=-NormalSlave(3,2)*crhs2;
        rLocalRHS[3]+=-NormalSlave(3,0)*crhs3;
        rLocalRHS[4]+=-NormalSlave(3,1)*crhs3;
        rLocalRHS[5]+=-NormalSlave(3,2)*crhs3;
        rLocalRHS[6]+=-NormalSlave(3,0)*crhs4;
        rLocalRHS[7]+=-NormalSlave(3,1)*crhs4;
        rLocalRHS[8]+=-NormalSlave(3,2)*crhs4;
        rLocalRHS[9]+=NormalSlave(3,0)*crhs5;
        rLocalRHS[10]+=NormalSlave(3,1)*crhs5;
        rLocalRHS[11]+=NormalSlave(3,2)*crhs5;
        rLocalRHS[12]+=NormalSlave(3,0)*crhs6;
        rLocalRHS[13]+=NormalSlave(3,1)*crhs6;
        rLocalRHS[14]+=NormalSlave(3,2)*crhs6;
        rLocalRHS[15]+=NormalSlave(3,0)*crhs7;
        rLocalRHS[16]+=NormalSlave(3,1)*crhs7;
        rLocalRHS[17]+=NormalSlave(3,2)*crhs7;
        rLocalRHS[18]+=NormalSlave(3,0)*crhs8;
        rLocalRHS[19]+=NormalSlave(3,1)*crhs8;
        rLocalRHS[20]+=NormalSlave(3,2)*crhs8;
        rLocalRHS[24]+=-ScaleFactor*crhs0;
    }
}

